CREATE TABLE "AttendanceRecord" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"workDate" TEXT NOT NULL,"checkIn" DATETIME NOT NULL,"checkOut" DATETIME,"note" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "AttendanceRecord_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "AttendanceRecord_userId_workDate_key" ON "AttendanceRecord"("userId","workDate");
CREATE TABLE "EmployeeLeaveRequest" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"leaveDate" TEXT NOT NULL,"leaveType" TEXT NOT NULL DEFAULT 'PAID',"reason" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"reviewNote" TEXT,"reviewedBy" TEXT,"reviewedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "EmployeeLeaveRequest_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "EmployeeLeaveRequest_userId_leaveDate_key" ON "EmployeeLeaveRequest"("userId","leaveDate");
